const $=s=>document.querySelector(s),app=$('#app'),dialog=$('#dialog');
const state={token:null,tenant:null,restaurants:[],page:'overview',filter:'ALL',cart:null,menu:[],quote:null,base:localStorage.getItem('callchef-server')||'',events:null};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>(Number(n||0)/100).toLocaleString('fr-FR',{style:'currency',currency:'EUR'});
const clock=s=>new Date(s).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Paris'});
const date=s=>new Date(s).toLocaleDateString('fr-FR',{day:'numeric',month:'short',timeZone:'Europe/Paris'});
const statusNames={NEW:'Nouvelle',CONFIRMED:'Confirmée',PREPARING:'En préparation',READY:'Prête',COMPLETED:'Terminée',CANCELLED:'Annulée',IN_PROGRESS:'En cours',ORDER_CREATED:'Commande créée',NO_ORDER:'Sans commande',ABANDONED:'Abandonné',TRANSFERRED:'Transféré',FAILED:'Échec'};
const badge=s=>`<span class="status ${['CONFIRMED','COMPLETED','ORDER_CREATED','READY'].includes(s)?'good':['PREPARING','IN_PROGRESS'].includes(s)?'warn':['CANCELLED','FAILED'].includes(s)?'bad':''}">${esc(statusNames[s]||s)}</span>`;
const toast=m=>{const t=$('#toast');t.textContent=m;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',4500);};
async function api(path,method='GET',body){const r=await fetch(state.base+'/api'+path,{method,headers:{'Content-Type':'application/json',...(state.token?{Authorization:'Bearer '+state.token}:{}),...(state.tenant?{'X-Restaurant-Id':state.tenant}:{})},body:body?JSON.stringify(body):undefined});if(r.status===204)return;const data=await r.json().catch(()=>({error:'Le serveur CallChef ne répond pas. Vérifiez son adresse.'}));if(!r.ok)throw new Error(data.error||'Erreur de connexion');return data;}
const btn=(label,attrs='',cls='')=>`<button ${attrs} class="${cls}">${label}</button>`;
function modal(title,body){dialog.innerHTML=`<div class="dialog-head row between"><h2>${esc(title)}</h2><button data-close class="icon" aria-label="Fermer">×</button></div><div class="dialog-body">${body}</div>`;if(!dialog.open)dialog.showModal();}
dialog.addEventListener('click',e=>{if(e.target.closest('[data-close]'))dialog.close();});
function loginPage(){state.events?.abort();app.innerHTML=`<div class="login"><section class="login-art"><div class="brand"><img src="/favicon.svg" alt="">callchef<span class="muted">.</span></div><div><div class="voice-visual" aria-hidden="true">${[20,35,58,88,48,72,100,65,38,70,48,25,12].map(h=>`<i style="--h:${h}px"></i>`).join('')}</div><h1>Au téléphone,<br>on s’en occupe.<br><span>En cuisine, à vous.</span></h1><p>Vos appels, vos commandes et votre menu. Tout votre service, au même endroit.</p></div><small>CallChef · L’assistant vocal des restaurants</small></section><section class="login-main"><div class="login-card"><div class="eyebrow">Espace restaurateur</div><h2>Bienvenue chez vous.</h2><p class="muted">Connectez-vous pour retrouver votre service.</p><form id="login-form" class="stack"><label>Adresse email<input name="email" type="email" autocomplete="username" placeholder="vous@restaurant.fr" required></label><label>Mot de passe<input name="password" type="password" autocomplete="current-password" placeholder="Votre mot de passe" required></label><div id="login-error" class="error"></div><button class="primary">Se connecter</button></form><button class="text-button" id="server-button">Configurer la connexion au serveur</button><div class="login-footer">Première installation ? <a href="/guide.html">Ouvrir le guide de démarrage</a>.<p class="privacy">Aucune donnée de démonstration n’est présentée comme une commande réelle.</p></div></div></section></div>`;
 $('#login-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const d=Object.fromEntries(new FormData(e.target));const {token}=await api('/login','POST',d);state.token=token;await loadMe();shell();await render();streamEvents();}catch(err){$('#login-error').textContent=err.message;}finally{b.disabled=false;}};
 $('#server-button').onclick=()=>{modal('Connecter votre serveur',`<p>Après le déploiement, collez l’adresse HTTPS du serveur CallChef indiquée par votre hébergeur.</p><form id="server-form" class="stack"><label>Adresse du serveur<input name="url" type="url" value="${esc(state.base)}" placeholder="https://votre-serveur.example.com"></label><p class="helper">Laissez vide si le dashboard et le serveur sont hébergés ensemble. Cette adresse ne contient aucune clé API.</p><div class="form-actions"><button class="primary">Enregistrer</button></div></form>`);$('#server-form').onsubmit=e=>{e.preventDefault();const url=new FormData(e.target).get('url').trim().replace(/\/$/,'');if(url){const u=new URL(url);if(u.protocol!=='https:'&&!(u.protocol==='http:'&&['localhost','127.0.0.1'].includes(u.hostname)))return toast('Une adresse HTTPS est requise.');if(u.username||u.password||u.search||u.hash)return toast('Utilisez une adresse sans identifiants ni paramètres.');}state.base=url;localStorage.setItem('callchef-server',url);dialog.close();toast('Adresse du serveur enregistrée');};};}
async function loadMe(){const me=await api('/me');state.restaurants=me.restaurants;state.email=me.user.email;if(!state.tenant||!me.restaurants.some(r=>r.id===state.tenant))state.tenant=me.restaurants[0]?.id;}
const nav=[['overview','◫','Vue d’ensemble'],['orders','▤','Commandes'],['calls','◉','Appels'],['menu','▦','Menu'],['customers','♧','Clients'],['settings','⚙','Réglages']];
function shell(){app.innerHTML=`<aside class="sidebar"><div class="brand"><img src="/favicon.svg" alt="">callchef.</div><nav>${nav.map(([id,icon,label])=>`<button class="nav-button ${state.page===id?'active':''}" data-page="${id}"><span class="nav-icon" aria-hidden="true">${icon}</span>${label}</button>`).join('')}</nav><div class="sidebar-bottom"><small>Votre service, en un coup d’œil.</small><br><button id="logout">Se déconnecter</button></div></aside><main class="main"><header class="topbar"><div class="row"><select class="restaurant-switch" id="restaurant-switch" aria-label="Restaurant">${state.restaurants.map(r=>`<option value="${r.id}" ${state.tenant===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></div><div class="row"><small class="muted">Espace restaurateur</small><span class="avatar">${esc(state.email?.slice(0,2).toUpperCase())}</span></div></header><div id="workspace" class="workspace"></div></main>`;
 app.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;state.filter='ALL';shell();safeRender();});$('#logout').onclick=async()=>{await api('/logout','POST').catch(()=>{});state.token=null;loginPage();};$('#restaurant-switch').onchange=e=>{state.tenant=e.target.value;state.cart=null;state.quote=null;shell();safeRender();streamEvents();};}
const heading=(title,subtitle,actions='')=>`<div class="page-heading row between"><div><div class="eyebrow">Votre restaurant</div><h1>${title}</h1><p class="muted" style="margin:0">${subtitle}</p></div><div class="row">${actions}</div></div>`;
const empty=(title,body,action='')=>`<div class="empty"><div class="empty-symbol" aria-hidden="true">▤</div><h3>${title}</h3><p>${body}</p>${action}</div>`;
function ordersTable(orders){if(!orders.length)return empty('La cuisine attend sa première commande.','Les commandes confirmées apparaîtront ici automatiquement.');return `<div class="table-wrap"><table><thead><tr><th>Commande</th><th>Client</th><th>Service</th><th>Total</th><th>Statut</th></tr></thead><tbody>${orders.map(o=>`<tr data-order="${o.id}" tabindex="0" role="button" aria-label="Ouvrir commande ${o.number}"><td><span class="cell-title">#${o.number}</span><small>${date(o.created_at)} · ${clock(o.created_at)}</small></td><td><span class="cell-title">${esc(o.snapshot.customer.name)}</span><small>${o.snapshot.items.reduce((s,i)=>s+i.quantity,0)} articles</small></td><td>${o.snapshot.fulfillment==='DELIVERY'?'Livraison':'À emporter'}</td><td class="mono"><b>${money(o.total_cents)}</b></td><td>${badge(o.status)}</td></tr>`).join('')}</tbody></table></div>`;}
function bindOrders(){document.querySelectorAll('[data-order]').forEach(el=>{el.onclick=()=>orderDetail(el.dataset.order);el.onkeydown=e=>{if(e.key==='Enter')el.click();};});}
async function safeRender(){try{await render();}catch(e){$('#workspace').innerHTML=`<div class="error">${esc(e.message)}</div><button id="retry">Réessayer</button>`;$('#retry').onclick=safeRender;}}
async function render(){const w=$('#workspace');if(!w)return;const page=state.page;let html='';
 if(page==='overview'){const [d,s]=await Promise.all([api('/overview'),api('/settings')]);html=heading('Le service, en direct.',new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long',timeZone:d.restaurant.settings.timezone}),btn('Tester une commande','id="test-cart"','dark'))+`<div class="stats">${[['Chiffre d’affaires',money(d.revenueCents),'Commandes hors annulations','accent'],['Commandes',d.orders,'Confirmées aujourd’hui',''],['Appels reçus',d.calls,`${d.answered} pris en charge par l’IA`,''],['Panier moyen',money(d.averageCents),`${d.conversion} % de conversion des appels`,'']].map(([l,v,s,c])=>`<article class="stat ${c}"><div class="stat-label">${l}</div><div class="stat-value mono">${v}</div><small>${s}</small></article>`).join('')}</div><div class="overview-grid"><section class="panel"><div class="panel-heading row between"><h2>Dernières commandes</h2><span class="status good"><span class="dot"></span>Actualisation automatique</span></div>${ordersTable(d.recentOrders)}</section><div><section class="panel"><div class="panel-heading"><h2>Votre assistant</h2></div><div class="panel-body"><div class="connection"><span>Prise de commande</span><span class="status ${s.settings.acceptingOrders?'good':'warn'}">${s.settings.acceptingOrders?'Activée':'En pause'}</span></div><div class="connection"><span>Moteur vocal</span><span class="status ${s.connections.voice?'good':'warn'}">${s.connections.voice?'Configuré':'À connecter'}</span></div><div class="connection"><span>Numéro</span><small>${s.phoneNumbers.length?esc(s.phoneNumbers[0].number):'À rattacher'}</small></div><p class="helper" style="margin:1rem 0 0">Le test téléphonique valide le fonctionnement réel des connexions.</p></div></section><section class="panel"><div class="panel-heading"><h2>Activité du jour</h2></div><div class="panel-body"><div class="mini-metric"><span>Minutes d’appel</span><b>${d.minutes.toFixed(1)}</b></div><div class="mini-metric"><span>Coût IA estimé</span><b>${d.aiCostEur===null?'Non chiffré':money(d.aiCostEur*100)}</b></div><div class="mini-metric"><span>Commandes par appel</span><b>${d.conversion} %</b></div></div></section></div></div>${!s.phoneNumbers.length?'<div class="note">Votre restaurant est prêt à être configuré. <a href="/guide.html" target="_blank">Suivez le guide pour connecter votre premier numéro.</a></div>':''}`;}
 if(page==='orders'){const list=await api('/orders');html=heading('Commandes','La bonne commande, au bon moment.',btn('Tester une commande','id="test-cart"','dark'))+`<div class="toolbar">${[['ALL','Toutes'],['CONFIRMED','Confirmées'],['PREPARING','En préparation'],['READY','Prêtes'],['COMPLETED','Terminées']].map(([v,l])=>btn(l,`data-filter="${v}"`,state.filter===v?'selected':'')).join('')}</div><section class="panel">${ordersTable(list.filter(o=>state.filter==='ALL'||o.status===state.filter))}</section>`;}
 if(page==='calls'){const calls=await api('/calls');html=heading('Appels','Chaque conversation, du bonjour à la commande.')+`<section class="panel">${calls.length?`<div class="table-wrap"><table><thead><tr><th>Appelant</th><th>Date</th><th>Durée</th><th>Résultat</th><th>Coût estimé</th></tr></thead><tbody>${calls.map(c=>`<tr data-call="${c.id}" tabindex="0" role="button"><td><b>${esc(c.caller||'Numéro masqué')}</b></td><td>${date(c.started_at)} · ${clock(c.started_at)}</td><td>${c.ended_at?Math.round((new Date(c.ended_at)-new Date(c.started_at))/1000)+' s':'En cours'}</td><td>${badge(c.outcome)}</td><td>${c.ai_cost_eur!==null&&c.telephony_cost_eur!==null?money((Number(c.ai_cost_eur)+Number(c.telephony_cost_eur))*100):'Non chiffré'}</td></tr>`).join('')}</tbody></table></div>`:empty('Le premier appel sera bientôt ici.','Retrouvez les conversations, les durées et le résultat de chaque appel.')}</section>`;}
 if(page==='menu'){state.menu=await api('/menu');html=heading('Votre menu','Les produits et les prix que votre assistant peut proposer.',btn('Ajouter un produit','id="add-product"','dark'))+`<div class="note">Ce catalogue fait foi pour les commandes. Vérifiez les prix, les ingrédients et les disponibilités avant d’ouvrir le service.</div>`+[...new Set(state.menu.map(p=>p.category))].map(cat=>`<h2 class="category">${esc(cat)}</h2><div class="product-grid">${state.menu.filter(p=>p.category===cat).map(p=>`<article class="product"><div class="row between"><h3>${esc(p.name)}</h3></div><p class="helper">${p.options.length?`${p.options.length} groupes de choix`:'Sans options'} · ${p.ingredients?'Ingrédients renseignés':'Ingrédients à renseigner'}</p><div class="row between"><span class="price">${money(p.price_cents)}</span><span class="status ${p.available?'good':''}">${p.available?'Disponible':'Épuisé'}</span></div><button class="small" data-product="${p.id}" style="margin-top:1rem">Modifier</button></article>`).join('')}</div>`).join('');}
 if(page==='customers'){const customers=await api('/customers');html=heading('Clients','Les clients de vos commandes confirmées.')+`<section class="panel">${customers.length?`<div class="table-wrap"><table><thead><tr><th>Client</th><th>Téléphone</th><th>Commandes</th><th>Total commandé</th></tr></thead><tbody>${customers.map(c=>`<tr><td><b>${esc(c.name)}</b></td><td>${esc(c.phone)}</td><td>${c.orders}</td><td>${money(c.total_cents)}</td></tr>`).join('')}</tbody></table></div>`:empty('Votre carnet client se remplit tout seul.','Les coordonnées sont enregistrées lorsqu’une commande est confirmée.')}</section>`;}
 if(page==='settings'){const r=await api('/settings');state.settings=r;html=settingsHtml(r);}
 if(state.page!==page)return;w.innerHTML=html;bindOrders();$('#test-cart')?.addEventListener('click',()=>basket());document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;safeRender();});document.querySelectorAll('[data-call]').forEach(el=>{el.onclick=()=>callDetail(el.dataset.call);el.onkeydown=e=>{if(e.key==='Enter')el.click();};});$('#add-product')?.addEventListener('click',()=>productEditor());document.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>productEditor(state.menu.find(p=>p.id===b.dataset.product)));if(page==='settings')bindSettings();}
const transcript=arr=>arr?.length?`<div class="transcript">${arr.map(t=>`<div class="bubble ${t.role==='user'?'user':''}"><small>${t.role==='user'?'Client':'CallChef'}</small>${esc(t.text)}</div>`).join('')}</div>`:'<p class="muted">Aucune transcription disponible.</p>';
async function orderDetail(id){try{const o=await api('/orders/'+id),s=o.snapshot;const next={NEW:['CONFIRMED','Confirmer'],CONFIRMED:['PREPARING','Passer en préparation'],PREPARING:['READY','Commande prête'],READY:['COMPLETED','Marquer comme remise']}[o.status];modal('Commande #'+o.number,`<div class="row between"><p><b>${esc(s.customer.name)}</b><br><small>${esc(s.customer.phone)} · ${clock(o.created_at)}</small></p>${badge(o.status)}</div><p>${s.fulfillment==='DELIVERY'?'Livraison · '+esc(s.customer.address)+', '+esc(s.customer.postcode):'Retrait sur place'}${s.customer.instructions?'<br>'+esc(s.customer.instructions):''}</p>${s.items.map(i=>`<div class="order-line"><div class="row between"><b>${i.quantity} × ${esc(i.name)}</b><b>${money(i.totalCents)}</b></div><small>${i.options.map(o=>esc(o.name)).join(' · ')}</small></div>`).join('')}<div class="row between total"><span>Total ${s.deliveryFeeCents?'(livraison incluse)':''}</span><span>${money(o.total_cents)}</span></div><div class="form-actions">${!['COMPLETED','CANCELLED'].includes(o.status)?btn('Annuler la commande','id="cancel-order"','danger'):''}${next?btn(next[1],'id="next-status"','primary'):''}</div><h3 style="margin-top:2rem">Conversation</h3>${transcript(o.call?.transcript)}`);$('#next-status')?.addEventListener('click',async()=>{await api('/orders/'+id,'PATCH',{status:next[0]});dialog.close();toast('Statut mis à jour');safeRender();});$('#cancel-order')?.addEventListener('click',()=>{modal('Annuler la commande #'+o.number,`<p>La commande sera marquée comme annulée. Le client ne reçoit pas de notification automatique : prévenez-le directement.</p><div class="form-actions"><button data-close>Revenir</button><button id="confirm-cancel" class="danger">Confirmer l’annulation</button></div>`);$('#confirm-cancel').onclick=async()=>{await api('/orders/'+id,'PATCH',{status:'CANCELLED'});dialog.close();safeRender();};});}catch(e){toast(e.message);}}
async function callDetail(id){try{const c=await api('/calls/'+id);modal('Appel de '+(c.caller||'numéro masqué'),`<div class="row between"><p>${date(c.started_at)} · ${clock(c.started_at)}</p>${badge(c.outcome)}</div>${transcript(c.transcript)}<details style="margin-top:1.5rem"><summary>Journal de traitement</summary><div class="call-events">${c.events.map(e=>`<div><small>${clock(e.created_at)}</small> <code>${esc(e.type)}</code>${e.data.reason?' · '+esc(e.data.reason):''}</div>`).join('')}</div></details>`);}catch(e){toast(e.message);}}
function settingsHtml(r){const s=r.settings;return heading('Réglages','Votre restaurant, votre façon de répondre.',btn('Nouveau restaurant','id="new-restaurant"'))+`<form id="settings-form"><div class="settings-layout"><div><section class="panel"><div class="panel-heading"><h2>Le restaurant</h2></div><div class="panel-body stack"><label>Nom<input name="name" value="${esc(r.name)}" required></label><label>Adresse<input name="address" value="${esc(s.address)}" required></label><label class="check"><input name="acceptingOrders" type="checkbox" ${s.acceptingOrders?'checked':''}>Accepter les commandes pendant les horaires d’ouverture</label><label>Numéro de transfert humain<input name="humanTransferNumber" value="${esc(s.humanTransferNumber)}" placeholder="+33612345678"></label><label>Fuseau horaire<input name="timezone" value="${esc(s.timezone)}" required></label></div></section><section class="panel"><div class="panel-heading"><h2>Horaires de prise de commande</h2></div><div class="panel-body stack"><p class="helper">Exemple : 11:00-14:00, 18:00-23:00. Laissez vide pour fermer ce jour. Pour passer minuit, répartissez les créneaux sur les deux jours.</p>${['Dimanche','Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi'].map((d,i)=>`<div class="hours-row"><label for="day-${i}">${d}</label><input id="day-${i}" name="day-${i}" value="${esc((s.openingHours[i]||[]).map(a=>a.join('-')).join(', '))}" placeholder="Fermé"></div>`).join('')}</div></section><section class="panel"><div class="panel-heading"><h2>Votre assistant vocal</h2></div><div class="panel-body stack"><label>Accueil<textarea name="greeting" rows="3" required>${esc(s.greeting)}</textarea></label><label>Information sur la transcription<textarea name="privacyNotice" rows="3" required>${esc(s.privacyNotice)}</textarea></label><div class="grid2"><label>Voix<select name="voice">${['marin','cedar','alloy','ash','ballad','coral','echo','sage','shimmer','verse'].map(v=>`<option ${v===s.voice?'selected':''}>${v}</option>`).join('')}</select></label><label>Conservation des transcriptions (jours)<input type="number" min="1" max="90" name="retentionDays" value="${s.retentionDays}"></label></div><label class="check"><input type="checkbox" name="upsellEnabled" ${s.upsellEnabled?'checked':''}>Autoriser une suggestion de produit complémentaire</label><p class="helper">Aucun enregistrement audio n’est stocké par CallChef. La purge des transcriptions doit être planifiée sur le serveur.</p></div></section></div><div><section class="panel"><div class="panel-heading"><h2>Livraison</h2></div><div class="panel-body stack"><label class="check"><input name="deliveryEnabled" type="checkbox" ${s.deliveryEnabled?'checked':''}>Activer la livraison</label><label>Codes postaux desservis<input name="deliveryPostcodes" value="${esc(s.deliveryPostcodes.join(', '))}" placeholder="13010, 13009"></label><p class="helper">La zone du MVP est définie par codes postaux. Aucun calcul de distance ou de rayon n’est appliqué.</p><div class="grid2"><label>Minimum (€)<input type="number" step="0.01" min="0" name="minimumOrder" value="${s.minimumOrderCents/100}"></label><label>Frais (€)<input type="number" step="0.01" min="0" name="deliveryFee" value="${s.deliveryFeeCents/100}"></label></div></div></section><section class="panel"><div class="panel-heading"><h2>Connexions</h2></div><div class="panel-body"><div class="connection"><span>OpenAI</span><span class="status ${r.connections.voice?'good':'warn'}">${r.connections.voice?'Clé configurée':'À configurer'}</span></div><div class="connection"><span>Twilio</span><span class="status ${r.connections.telephony?'good':'warn'}">${r.connections.telephony?'Configuré':'À configurer'}</span></div><p class="helper" style="margin-top:1rem">Numéro : ${r.phoneNumbers.map(n=>esc(n.number)).join(', ')||'aucun numéro rattaché'}</p><a href="/guide.html" target="_blank">Guide de connexion</a></div></section><div id="settings-error" class="error"></div><button class="primary" style="width:100%">Enregistrer les réglages</button></div></div></form>`;}
function bindSettings(){$('#settings-form').onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target),s=structuredClone(state.settings.settings);for(const k of ['address','timezone','humanTransferNumber','greeting','privacyNotice','voice'])s[k]=f.get(k);for(const k of ['acceptingOrders','deliveryEnabled','upsellEnabled'])s[k]=f.has(k);s.retentionDays=Number(f.get('retentionDays'));s.minimumOrderCents=Math.round(Number(f.get('minimumOrder'))*100);s.deliveryFeeCents=Math.round(Number(f.get('deliveryFee'))*100);s.deliveryPostcodes=f.get('deliveryPostcodes').split(',').map(s=>s.trim()).filter(Boolean);s.openingHours=Object.fromEntries(Array.from({length:7},(_,i)=>[i,f.get('day-'+i).split(',').map(s=>s.trim()).filter(Boolean).map(v=>v.split('-').map(x=>x.trim()))]));await api('/settings','PATCH',{name:f.get('name'),settings:s});await loadMe();shell();await render();toast('Réglages enregistrés');}catch(err){$('#settings-error').textContent=err.message;}};$('#new-restaurant').onclick=()=>{modal('Créer un restaurant',`<form id="new-restaurant-form" class="stack"><label>Nom du restaurant<input name="name" required minlength="2"></label><p class="helper">Un menu d’exemple sera créé. Vérifiez-le avant d’activer les commandes.</p><button class="primary">Créer le restaurant</button></form>`);$('#new-restaurant-form').onsubmit=async e=>{e.preventDefault();try{const r=await api('/restaurants','POST',Object.fromEntries(new FormData(e.target)));state.tenant=r.id;await loadMe();dialog.close();shell();safeRender();streamEvents();}catch(err){toast(err.message);}};};}
function productEditor(product){const p=structuredClone(product||{category:'Burgers',name:'',price_cents:0,available:true,ingredients:null,options:[]});modal(product?'Modifier le produit':'Nouveau produit',`<form id="product-form" class="stack"><label>Nom<input name="name" value="${esc(p.name)}" required></label><div class="grid2"><label>Catégorie<input name="category" value="${esc(p.category)}" required></label><label>Prix (€)<input name="price" type="number" min="0" step=".01" value="${p.price_cents/100}" required></label></div><label class="check"><input name="available" type="checkbox" ${p.available?'checked':''}>Disponible</label><label>Ingrédients vérifiés<textarea name="ingredients" rows="2" placeholder="Laissez vide si non renseignés">${esc(p.ingredients||'')}</textarea></label><div><h3>Choix et suppléments</h3><div id="option-groups"></div><button type="button" id="add-group" class="small" style="margin-top:.8rem">Ajouter un groupe de choix</button></div><div class="error" id="product-error"></div><div class="form-actions"><button class="primary">Enregistrer le produit</button></div></form>`);
 const draw=()=>{$('#option-groups').innerHTML=p.options.map((g,i)=>`<div class="option-group"><div class="row between"><input aria-label="Nom du groupe" data-group="${i}" data-field="name" value="${esc(g.name)}"><button type="button" data-remove-group="${i}" class="icon" aria-label="Supprimer groupe">×</button></div><div class="grid2" style="margin-top:.7rem"><label>Minimum<input type="number" min="0" data-group="${i}" data-field="min" value="${g.min}"></label><label>Maximum<input type="number" min="0" data-group="${i}" data-field="max" value="${g.max}"></label></div>${g.options.map((o,j)=>`<div class="option-row"><label>Choix<input data-group="${i}" data-option="${j}" data-field="name" value="${esc(o.name)}"></label><label>Extra (€)<input type="number" min="0" step=".01" data-group="${i}" data-option="${j}" data-field="priceCents" value="${o.priceCents/100}"></label><input type="checkbox" aria-label="Option disponible" data-group="${i}" data-option="${j}" data-field="available" ${o.available?'checked':''}></div>`).join('')}<button class="small" type="button" data-add-option="${i}" style="margin-top:.7rem">Ajouter un choix</button></div>`).join('');$('#option-groups').querySelectorAll('input').forEach(input=>input.oninput=()=>{const target=input.dataset.option!==undefined?p.options[input.dataset.group].options[input.dataset.option]:p.options[input.dataset.group];const key=input.dataset.field;target[key]=key==='available'?input.checked:key==='priceCents'?Math.round(Number(input.value)*100):['min','max'].includes(key)?Number(input.value):input.value;});document.querySelectorAll('[data-add-option]').forEach(b=>b.onclick=()=>{p.options[b.dataset.addOption].options.push({id:crypto.randomUUID(),name:'Nouveau choix',priceCents:0,available:true});draw();});document.querySelectorAll('[data-remove-group]').forEach(b=>b.onclick=()=>{p.options.splice(Number(b.dataset.removeGroup),1);draw();});};draw();$('#add-group').onclick=()=>{p.options.push({id:crypto.randomUUID(),name:'Choix',min:0,max:1,options:[{id:crypto.randomUUID(),name:'Option',priceCents:0,available:true}]});draw();};$('#product-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await api('/menu','POST',{...(p.id?{id:p.id}:{}),name:f.get('name'),category:f.get('category'),price_cents:Math.round(Number(f.get('price'))*100),available:f.has('available'),ingredients:f.get('ingredients')||null,options:p.options});dialog.close();toast('Menu enregistré');safeRender();}catch(err){$('#product-error').textContent=err.message;}};}
async function basket(){try{state.menu=await api('/menu');if(!state.cart)state.cart=(await api('/carts','POST')).id;const c=await api('/carts/'+state.cart);modal('Tester le parcours de commande',`<p class="helper">Ce test utilise le vrai panier et crée une commande réelle dans votre dashboard. Il permet de vérifier les règles avant le premier appel.</p><form id="basket-add" class="stack"><div class="grid2"><label>Produit<select name="productId" id="basket-product">${state.menu.filter(p=>p.available).map(p=>`<option value="${p.id}">${esc(p.name)} · ${money(p.price_cents)}</option>`).join('')}</select></label><label>Quantité<input type="number" name="quantity" value="1" min="1" max="30"></label></div><div id="basket-options"></div><button>Ajouter au panier</button></form><div class="basket-items" style="margin-top:1.5rem">${c.items.length?c.items.map(i=>`<div class="basket-line row between"><div><b>${i.quantity} × ${esc(i.name)}</b><br><small>${i.options.map(o=>esc(o.name)).join(', ')}</small></div><div class="row"><b>${money(i.totalCents)}</b><button data-remove-item="${i.id}" class="icon" aria-label="Retirer">×</button></div></div>`).join(''):'Panier vide'}<div class="total row between"><span>Total</span><span>${money(c.totalCents)}</span></div></div><form id="basket-customer" class="stack" style="margin-top:1.5rem"><div class="grid2"><label>Nom<input name="name" value="${esc(c.customer?.name||'')}" required></label><label>Téléphone<input name="phone" placeholder="+33612345678" value="${esc(c.customer?.phone||'')}" required></label></div><label>Service<select name="fulfillment"><option value="PICKUP">Retrait sur place</option><option value="DELIVERY" ${c.fulfillment==='DELIVERY'?'selected':''}>Livraison</option></select></label><div class="grid2"><label>Adresse de livraison<input name="address" value="${esc(c.customer?.address||'')}"></label><label>Code postal<input name="postcode" value="${esc(c.customer?.postcode||'')}"></label></div><button class="primary" ${!c.items.length?'disabled':''}>Vérifier et récapituler</button></form>`);
 const options=()=>{const p=state.menu.find(p=>p.id===$('#basket-product').value);$('#basket-options').innerHTML=p?.options.map(g=>`<fieldset class="option-group"><legend>${esc(g.name)} (${g.min} à ${g.max})</legend>${g.options.filter(o=>o.available).map(o=>`<label class="check"><input type="checkbox" name="optionIds" value="${esc(o.id)}">${esc(o.name)} ${o.priceCents?'· +'+money(o.priceCents):''}</label>`).join('')}</fieldset>`).join('')||'';};options();$('#basket-product').onchange=options;
 $('#basket-add').onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target);await api('/carts/'+state.cart+'/action','POST',{action:'addItemToCart',args:{productId:f.get('productId'),quantity:Number(f.get('quantity')),optionIds:f.getAll('optionIds')}});await basket();}catch(err){toast(err.message);}};
 document.querySelectorAll('[data-remove-item]').forEach(b=>b.onclick=async()=>{await api('/carts/'+state.cart+'/action','POST',{action:'removeCartItem',args:{itemId:b.dataset.removeItem}});basket();});
 $('#basket-customer').onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target);await api('/carts/'+state.cart+'/action','POST',{action:'setCustomer',args:{fulfillment:f.get('fulfillment'),customer:{name:f.get('name'),phone:f.get('phone'),address:f.get('address'),...(f.get('postcode')?{postcode:f.get('postcode')}:{})}}});const q=await api('/carts/'+state.cart+'/quote','POST');modal('Confirmer la commande',`<p>${esc(q.recap)}</p><div class="note">Cette validation transmet la commande au restaurant.</div><div class="form-actions"><button id="back-cart">Modifier</button><button id="confirm-cart" class="primary">Confirmer la commande</button></div>`);$('#back-cart').onclick=basket;$('#confirm-cart').onclick=async e=>{e.target.disabled=true;try{const o=await api('/carts/'+state.cart+'/confirm','POST',{quoteToken:q.quoteToken,confirmed:true});state.cart=null;dialog.close();toast('Commande #'+o.number+' créée');safeRender();}catch(err){toast(err.message);e.target.disabled=false;}};}catch(err){toast(err.message);}};
 }catch(e){toast(e.message);}}
async function streamEvents(){state.events?.abort();const controller=new AbortController();state.events=controller;try{const r=await fetch(state.base+'/api/events',{headers:{Authorization:'Bearer '+state.token,'X-Restaurant-Id':state.tenant},signal:controller.signal});if(!r.ok)throw new Error('stream');const reader=r.body.getReader(),decoder=new TextDecoder();let buffer='';while(true){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let index;while((index=buffer.indexOf('\n\n'))>=0){const chunk=buffer.slice(0,index);buffer=buffer.slice(index+2);if(chunk.startsWith('data:')&&['overview','orders'].includes(state.page)&&!dialog.open)await safeRender();}}}catch{}if(!controller.signal.aborted&&state.token)setTimeout(streamEvents,3000);}
window.addEventListener('unhandledrejection',e=>{e.preventDefault();toast(e.reason?.message||'Action impossible. Réessayez.');});
loginPage();
